Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "width": {"step": 38},
  "height": "container",
  "autosize": {"type": "fit-y", "contains": "padding"},
  "padding": {"left": 4, "right": 6, "top": 6, "bottom": 2},
  "transform": [
    {
      "joinaggregate": [
        {"op": "distinct", "field": "client_name", "as": "nClients"}
      ]
    },
    {
      "calculate": "datum.nClients > 1 ? datum.client_name : datum.account",
      "as": "cat"
    },
    {
      "aggregate": [{"op": "sum", "field": "Selected Revenue", "as": "rev"}],
      "groupby": ["cat"]
    },
    {
      "window": [{"op": "sum", "field": "rev", "as": "cumRev"}],
      "sort": [{"field": "rev", "order": "descending"}],
      "frame": [null, 0]
    },
    {"joinaggregate": [{"op": "sum", "field": "rev", "as": "total"}]},
    {"calculate": "datum.cumRev / datum.total", "as": "cumShare"},
    {
      "window": [{"op": "rank", "as": "rnk"}],
      "sort": [{"field": "rev", "order": "descending"}]
    },
    {"filter": "datum.rnk <= 20"}
  ],
  "layer": [
    {
      "layer": [
        {
          "mark": {
            "type": "bar",
            "cornerRadiusEnd": 2,
            "width": {"band": 0.7}
          },
          "encoding": {
            "x": {
              "field": "cat",
              "type": "nominal",
              "sort": {"field": "rev", "op": "max", "order": "descending"},
              "axis": {
                "labelAngle": -40,
                "labelLimit": 74,
                "labelOverlap": false,
                "title": null,
                "labelColor": "#5A5A5A",
                "labelFontSize": 9,
                "domainColor": "#D0D0D0",
                "ticks": false
              }
            },
            "y": {"field": "rev", "type": "quantitative", "axis": null},
            "color": {
              "condition": {
                "test": "datum.cumShare <= 0.8",
                "value": "#3A7D44"
              },
              "value": "#CBD5CC"
            }
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "center",
            "baseline": "bottom",
            "dy": -3,
            "fontSize": 9, "fontWeight": 700,
            "fill": "#1A5C35"
          },
          "encoding": {
            "x": {
              "field": "cat",
              "type": "nominal",
              "sort": {"field": "rev", "op": "max", "order": "descending"}
            },
            "y": {"field": "rev", "type": "quantitative"},
            "text": {
              "field": "rev",
              "type": "quantitative",
              "format": "$,.2s"
            }
          }
        }
      ]
    },
    {
      "layer": [
        {
          "mark": {
            "type": "line",
            "color": "#3A7D44",
            "strokeWidth": 2,
            "point": {"filled": true, "fill": "#3A7D44", "size": 26}
          },
          "encoding": {
            "x": {
              "field": "cat",
              "type": "nominal",
              "sort": {"field": "rev", "op": "max", "order": "descending"}
            },
            "y": {
              "field": "cumShare",
              "type": "quantitative",
              "scale": {"domain": [0, 1]},
              "axis": null
            }
          }
        },
        {
          "transform": [{"filter": "datum.cumShare <= 0.82"}],
          "mark": {
            "type": "text",
            "align": "center",
            "baseline": "bottom",
            "dy": -9,
            "fontSize": 9, "fontWeight": 700,
            "fill": "#333333"
          },
          "encoding": {
            "x": {
              "field": "cat",
              "type": "nominal",
              "sort": {"field": "rev", "op": "max", "order": "descending"}
            },
            "y": {
              "field": "cumShare",
              "type": "quantitative",
              "scale": {"domain": [0, 1]}
            },
            "text": {
              "field": "cumShare",
              "type": "quantitative",
              "format": ".0%"
            }
          }
        },
        {
          "mark": {
            "type": "rule",
            "color": "#F68E1E",
            "strokeDash": [5, 4],
            "strokeWidth": 1.5
          },
          "encoding": {
            "y": {
              "datum": 0.8,
              "type": "quantitative",
              "scale": {"domain": [0, 1]}
            }
          }
        }
      ]
    }
  ],
  "resolve": {"scale": {"y": "independent"}}
}'
